    "<span class=\"eq\">NH<sub>4</sub>NO<sub>3</sub>(s) → NH<sub>4</sub>⁺(aq) + NO<sub>3</sub>⁻(aq)&emsp;Δ<i>H</i> = +25.7 kJ mol⁻¹</span>",
    "<span class=\"eq\">CaCl<sub>2</sub>(s) → Ca<sup>2+</sup>(aq) + 2 Cl⁻(aq)&emsp;Δ<i>H</i> = −82.8 kJ mol⁻¹</span>",
